-- BEBD3-002 / V001. Esquema fiel al DBML aprobado; sin tablas adicionales.
BEGIN;
CREATE TABLE "Rol" (
  "idRol" integer GENERATED BY DEFAULT AS IDENTITY,
  "nombre" varchar(30) NOT NULL,
  "descripcion" text NOT NULL,
  CONSTRAINT "pk_rol" PRIMARY KEY ("idRol"),
  CONSTRAINT "uq_rol_nombre" UNIQUE ("nombre")
);
CREATE TABLE "Permiso" (
  "idPermiso" integer GENERATED BY DEFAULT AS IDENTITY,
  "codigo" varchar(100) NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "descripcion" text,
  CONSTRAINT "pk_permiso" PRIMARY KEY ("idPermiso"),
  CONSTRAINT "uq_permiso_codigo" UNIQUE ("codigo")
);
CREATE TABLE "Usuario" (
  "idUsuario" uuid NOT NULL,
  "idRol" int NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "correo" varchar(255) NOT NULL,
  "passwordHash" varchar(255),
  "estado" varchar(20) NOT NULL DEFAULT 'Activo',
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  "fechaActualizacion" timestamptz,
  CONSTRAINT "pk_usuario" PRIMARY KEY ("idUsuario"),
  CONSTRAINT "uq_usuario_correo" UNIQUE ("correo")
);
CREATE TABLE "UsuarioPermiso" (
  "idUsuario" uuid NOT NULL,
  "idPermiso" int NOT NULL,
  "habilitado" boolean NOT NULL DEFAULT true,
  "idAdministradorAsignador" uuid,
  "fechaAsignacion" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_usuariopermiso" PRIMARY KEY ("idUsuario", "idPermiso")
);
CREATE TABLE "Estudiante" (
  "idEstudiante" uuid NOT NULL,
  "idUsuario" uuid NOT NULL,
  "apodo" varchar(80),
  "avatarConfig" jsonb,
  "fechaRegistro" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_estudiante" PRIMARY KEY ("idEstudiante"),
  CONSTRAINT "uq_estudiante_idusuario" UNIQUE ("idUsuario")
);
CREATE TABLE "Caso" (
  "idCaso" uuid NOT NULL,
  "idDocente" uuid NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "historia" text,
  "desarrolloSituacional" text,
  "tiempoEstimadoSegundos" int NOT NULL,
  "estado" varchar(20) NOT NULL DEFAULT 'Borrador',
  "activo" boolean NOT NULL DEFAULT true,
  "fechaBloqueoAcademico" timestamptz,
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  "fechaActualizacion" timestamptz,
  CONSTRAINT "pk_caso" PRIMARY KEY ("idCaso")
);
CREATE TABLE "Escenario" (
  "idEscenario" uuid NOT NULL,
  "idCaso" uuid NOT NULL,
  "titulo" varchar(200),
  "contexto" text,
  "instrucciones" text,
  "orden" int NOT NULL,
  "activo" boolean NOT NULL DEFAULT true,
  CONSTRAINT "pk_escenario" PRIMARY KEY ("idEscenario"),
  CONSTRAINT "uq_escenario_idx1" UNIQUE ("idCaso", "orden")
);
CREATE TABLE "Pregunta" (
  "idPregunta" uuid NOT NULL,
  "idEscenario" uuid NOT NULL,
  "enunciado" text NOT NULL,
  "textoAyuda" text,
  "estadoEdicion" varchar(20) NOT NULL DEFAULT 'Borrador',
  "visible" boolean NOT NULL DEFAULT true,
  "orden" int NOT NULL,
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  "fechaActualizacion" timestamptz,
  CONSTRAINT "pk_pregunta" PRIMARY KEY ("idPregunta"),
  CONSTRAINT "uq_pregunta_idx1" UNIQUE ("idEscenario", "orden")
);
CREATE TABLE "OpcionRespuesta" (
  "idOpcion" uuid NOT NULL,
  "idPregunta" uuid NOT NULL,
  "texto" text NOT NULL,
  "esCorrecta" boolean NOT NULL DEFAULT false,
  "explicacion" text,
  "orden" int NOT NULL,
  CONSTRAINT "pk_opcionrespuesta" PRIMARY KEY ("idOpcion"),
  CONSTRAINT "uq_opcionrespuesta_idx1" UNIQUE ("idOpcion", "idPregunta"),
  CONSTRAINT "uq_opcionrespuesta_idx2" UNIQUE ("idPregunta", "orden")
);
CREATE TABLE "Sesion" (
  "idSesion" uuid NOT NULL,
  "idCaso" uuid NOT NULL,
  "idDocenteProgramador" uuid NOT NULL,
  "nombreEspacioAcademico" varchar(150) NOT NULL,
  "inicioPrevisto" timestamptz NOT NULL,
  "finPrevisto" timestamptz NOT NULL,
  "fechaInicioReal" timestamptz,
  "fechaFinReal" timestamptz,
  "tiempoMaximoParticipacionSegundos" int NOT NULL,
  "lugarFisico" varchar(200),
  "mensajePersonalizado" text,
  "codigoAutorizacionHash" varchar(255),
  "estado" varchar(20) NOT NULL DEFAULT 'SinIniciar',
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_sesion" PRIMARY KEY ("idSesion")
);
CREATE TABLE "Convocatoria" (
  "idConvocatoria" uuid NOT NULL,
  "idSesion" uuid NOT NULL,
  "idEstudiante" uuid NOT NULL,
  "fechaConvocatoria" timestamptz NOT NULL DEFAULT now(),
  "estadoAutorizacion" varchar(25) NOT NULL DEFAULT 'Autorizado',
  "fechaRetiro" timestamptz,
  CONSTRAINT "pk_convocatoria" PRIMARY KEY ("idConvocatoria"),
  CONSTRAINT "uq_convocatoria_idx1" UNIQUE ("idSesion", "idEstudiante")
);
CREATE TABLE "Participacion" (
  "idParticipacion" uuid NOT NULL,
  "idConvocatoria" uuid NOT NULL,
  "estado" varchar(25) NOT NULL DEFAULT 'Pendiente',
  "fechaInicio" timestamptz,
  "fechaFin" timestamptz,
  "calificacionFinal" numeric(8,2),
  "detalleResultadoFinal" jsonb,
  CONSTRAINT "pk_participacion" PRIMARY KEY ("idParticipacion"),
  CONSTRAINT "uq_participacion_idconvocatoria" UNIQUE ("idConvocatoria")
);
CREATE TABLE "Intento" (
  "idIntento" uuid NOT NULL,
  "idParticipacion" uuid NOT NULL,
  "numeroIntento" int NOT NULL,
  "inicio" timestamptz NOT NULL,
  "fin" timestamptz,
  "limiteTemporal" timestamptz NOT NULL,
  "estado" varchar(25) NOT NULL,
  "estadoEvaluacion" varchar(25) NOT NULL DEFAULT 'Pendiente',
  "motivoFinalizacion" varchar(40),
  "idAutorizacion" uuid,
  CONSTRAINT "pk_intento" PRIMARY KEY ("idIntento"),
  CONSTRAINT "uq_intento_idautorizacion" UNIQUE ("idAutorizacion"),
  CONSTRAINT "uq_intento_idx1" UNIQUE ("idParticipacion", "numeroIntento")
);
CREATE TABLE "Respuesta" (
  "idRespuesta" uuid NOT NULL,
  "idIntento" uuid NOT NULL,
  "idPregunta" uuid NOT NULL,
  "idOpcionSeleccionada" uuid NOT NULL,
  "revision" int NOT NULL DEFAULT 1,
  "fechaActualizacion" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_respuesta" PRIMARY KEY ("idRespuesta"),
  CONSTRAINT "uq_respuesta_idx1" UNIQUE ("idIntento", "idPregunta")
);
CREATE TABLE "AutorizacionRepeticion" (
  "idAutorizacion" uuid NOT NULL,
  "idParticipacion" uuid NOT NULL,
  "idDocenteAutorizador" uuid NOT NULL,
  "motivo" text,
  "fechaAutorizacion" timestamptz NOT NULL DEFAULT now(),
  "fechaVencimiento" timestamptz,
  "estadoAutorizacion" varchar(25) NOT NULL DEFAULT 'Vigente',
  CONSTRAINT "pk_autorizacionrepeticion" PRIMARY KEY ("idAutorizacion"),
  CONSTRAINT "uq_autorizacionrepeticion_idx1" UNIQUE ("idAutorizacion", "idParticipacion")
);
CREATE TABLE "Rubrica" (
  "idRubrica" uuid NOT NULL,
  "idCaso" uuid NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "descripcion" text,
  "puntajeTotal" numeric(8,2),
  "definicionEvaluacion" jsonb,
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_rubrica" PRIMARY KEY ("idRubrica"),
  CONSTRAINT "uq_rubrica_idcaso" UNIQUE ("idCaso")
);
CREATE TABLE "RubricaPregunta" (
  "idRubricaPregunta" uuid NOT NULL,
  "idRubrica" uuid NOT NULL,
  "idPregunta" uuid NOT NULL,
  "valorPregunta" numeric(8,2) NOT NULL,
  "criterio" text,
  CONSTRAINT "pk_rubricapregunta" PRIMARY KEY ("idRubricaPregunta"),
  CONSTRAINT "uq_rubricapregunta_idpregunta" UNIQUE ("idPregunta"),
  CONSTRAINT "uq_rubricapregunta_idx1" UNIQUE ("idRubrica", "idPregunta")
);
CREATE TABLE "Calificacion" (
  "idCalificacion" uuid NOT NULL,
  "idIntento" uuid NOT NULL,
  "idRubrica" uuid NOT NULL,
  "valor" numeric(8,2) NOT NULL,
  "fechaCalculo" timestamptz NOT NULL DEFAULT now(),
  "detalleEvaluacion" jsonb NOT NULL,
  "versionPolitica" varchar(50),
  CONSTRAINT "pk_calificacion" PRIMARY KEY ("idCalificacion"),
  CONSTRAINT "uq_calificacion_idintento" UNIQUE ("idIntento")
);
CREATE TABLE "RetroalimentacionGeneral" (
  "idRetroalimentacion" uuid NOT NULL,
  "idParticipacion" uuid NOT NULL,
  "idDocente" uuid NOT NULL,
  "contenido" text NOT NULL,
  "fechaRegistro" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "pk_retroalimentaciongeneral" PRIMARY KEY ("idRetroalimentacion"),
  CONSTRAINT "uq_retroalimentaciongeneral_idparticipacion" UNIQUE ("idParticipacion")
);
CREATE TABLE "Aviso" (
  "idAviso" uuid NOT NULL,
  "idUsuarioDestino" uuid NOT NULL,
  "idParticipacion" uuid,
  "tipo" varchar(50) NOT NULL,
  "contenido" text NOT NULL,
  "claveEvento" varchar(150) NOT NULL,
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  "fechaLectura" timestamptz,
  CONSTRAINT "pk_aviso" PRIMARY KEY ("idAviso"),
  CONSTRAINT "uq_aviso_idx1" UNIQUE ("idUsuarioDestino", "claveEvento")
);
CREATE TABLE "EnvioCorreo" (
  "idEnvioCorreo" uuid NOT NULL,
  "idUsuarioDestino" uuid NOT NULL,
  "idConvocatoria" uuid,
  "correoDestino" varchar(255) NOT NULL,
  "asunto" varchar(255) NOT NULL,
  "contenido" text NOT NULL,
  "estadoEnvio" varchar(25) NOT NULL DEFAULT 'Pendiente',
  "numeroIntentos" int NOT NULL DEFAULT 0,
  "claveIdempotencia" varchar(150) NOT NULL,
  "ultimoError" text,
  "fechaCreacion" timestamptz NOT NULL DEFAULT now(),
  "fechaUltimoIntento" timestamptz,
  "proximoReintento" timestamptz,
  "fechaEnvio" timestamptz,
  CONSTRAINT "pk_enviocorreo" PRIMARY KEY ("idEnvioCorreo"),
  CONSTRAINT "uq_enviocorreo_claveidempotencia" UNIQUE ("claveIdempotencia")
);
ALTER TABLE "Usuario" ADD CONSTRAINT "fk_usuario_idrol" FOREIGN KEY ("idRol") REFERENCES "Rol" ("idRol") ON DELETE RESTRICT;
ALTER TABLE "Estudiante" ADD CONSTRAINT "fk_estudiante_idusuario" FOREIGN KEY ("idUsuario") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "UsuarioPermiso" ADD CONSTRAINT "fk_usuariopermiso_idusuario" FOREIGN KEY ("idUsuario") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "UsuarioPermiso" ADD CONSTRAINT "fk_usuariopermiso_idpermiso" FOREIGN KEY ("idPermiso") REFERENCES "Permiso" ("idPermiso") ON DELETE RESTRICT;
ALTER TABLE "UsuarioPermiso" ADD CONSTRAINT "fk_usuariopermiso_idadministradorasignador" FOREIGN KEY ("idAdministradorAsignador") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Caso" ADD CONSTRAINT "fk_caso_iddocente" FOREIGN KEY ("idDocente") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Escenario" ADD CONSTRAINT "fk_escenario_idcaso" FOREIGN KEY ("idCaso") REFERENCES "Caso" ("idCaso") ON DELETE RESTRICT;
ALTER TABLE "Pregunta" ADD CONSTRAINT "fk_pregunta_idescenario" FOREIGN KEY ("idEscenario") REFERENCES "Escenario" ("idEscenario") ON DELETE RESTRICT;
ALTER TABLE "OpcionRespuesta" ADD CONSTRAINT "fk_opcionrespuesta_idpregunta" FOREIGN KEY ("idPregunta") REFERENCES "Pregunta" ("idPregunta") ON DELETE RESTRICT;
ALTER TABLE "Sesion" ADD CONSTRAINT "fk_sesion_idcaso" FOREIGN KEY ("idCaso") REFERENCES "Caso" ("idCaso") ON DELETE RESTRICT;
ALTER TABLE "Sesion" ADD CONSTRAINT "fk_sesion_iddocenteprogramador" FOREIGN KEY ("idDocenteProgramador") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Convocatoria" ADD CONSTRAINT "fk_convocatoria_idsesion" FOREIGN KEY ("idSesion") REFERENCES "Sesion" ("idSesion") ON DELETE RESTRICT;
ALTER TABLE "Convocatoria" ADD CONSTRAINT "fk_convocatoria_idestudiante" FOREIGN KEY ("idEstudiante") REFERENCES "Estudiante" ("idEstudiante") ON DELETE RESTRICT;
ALTER TABLE "Participacion" ADD CONSTRAINT "fk_participacion_idconvocatoria" FOREIGN KEY ("idConvocatoria") REFERENCES "Convocatoria" ("idConvocatoria") ON DELETE RESTRICT;
ALTER TABLE "Intento" ADD CONSTRAINT "fk_intento_idparticipacion" FOREIGN KEY ("idParticipacion") REFERENCES "Participacion" ("idParticipacion") ON DELETE RESTRICT;
ALTER TABLE "AutorizacionRepeticion" ADD CONSTRAINT "fk_autorizacionrepeticion_idparticipacion" FOREIGN KEY ("idParticipacion") REFERENCES "Participacion" ("idParticipacion") ON DELETE RESTRICT;
ALTER TABLE "AutorizacionRepeticion" ADD CONSTRAINT "fk_autorizacionrepeticion_iddocenteautorizador" FOREIGN KEY ("idDocenteAutorizador") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Respuesta" ADD CONSTRAINT "fk_respuesta_idintento" FOREIGN KEY ("idIntento") REFERENCES "Intento" ("idIntento") ON DELETE RESTRICT;
ALTER TABLE "Respuesta" ADD CONSTRAINT "fk_respuesta_idpregunta" FOREIGN KEY ("idPregunta") REFERENCES "Pregunta" ("idPregunta") ON DELETE RESTRICT;
ALTER TABLE "Rubrica" ADD CONSTRAINT "fk_rubrica_idcaso" FOREIGN KEY ("idCaso") REFERENCES "Caso" ("idCaso") ON DELETE RESTRICT;
ALTER TABLE "RubricaPregunta" ADD CONSTRAINT "fk_rubricapregunta_idrubrica" FOREIGN KEY ("idRubrica") REFERENCES "Rubrica" ("idRubrica") ON DELETE RESTRICT;
ALTER TABLE "RubricaPregunta" ADD CONSTRAINT "fk_rubricapregunta_idpregunta" FOREIGN KEY ("idPregunta") REFERENCES "Pregunta" ("idPregunta") ON DELETE RESTRICT;
ALTER TABLE "Calificacion" ADD CONSTRAINT "fk_calificacion_idintento" FOREIGN KEY ("idIntento") REFERENCES "Intento" ("idIntento") ON DELETE RESTRICT;
ALTER TABLE "Calificacion" ADD CONSTRAINT "fk_calificacion_idrubrica" FOREIGN KEY ("idRubrica") REFERENCES "Rubrica" ("idRubrica") ON DELETE RESTRICT;
ALTER TABLE "RetroalimentacionGeneral" ADD CONSTRAINT "fk_retroalimentaciongeneral_idparticipacion" FOREIGN KEY ("idParticipacion") REFERENCES "Participacion" ("idParticipacion") ON DELETE RESTRICT;
ALTER TABLE "RetroalimentacionGeneral" ADD CONSTRAINT "fk_retroalimentaciongeneral_iddocente" FOREIGN KEY ("idDocente") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Aviso" ADD CONSTRAINT "fk_aviso_idusuariodestino" FOREIGN KEY ("idUsuarioDestino") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "Aviso" ADD CONSTRAINT "fk_aviso_idparticipacion" FOREIGN KEY ("idParticipacion") REFERENCES "Participacion" ("idParticipacion") ON DELETE RESTRICT;
ALTER TABLE "EnvioCorreo" ADD CONSTRAINT "fk_enviocorreo_idusuariodestino" FOREIGN KEY ("idUsuarioDestino") REFERENCES "Usuario" ("idUsuario") ON DELETE RESTRICT;
ALTER TABLE "EnvioCorreo" ADD CONSTRAINT "fk_enviocorreo_idconvocatoria" FOREIGN KEY ("idConvocatoria") REFERENCES "Convocatoria" ("idConvocatoria") ON DELETE RESTRICT;
ALTER TABLE "Intento" ADD CONSTRAINT "fk_intento_idautorizacion_idparticipacion" FOREIGN KEY ("idAutorizacion", "idParticipacion") REFERENCES "AutorizacionRepeticion" ("idAutorizacion", "idParticipacion") ON DELETE RESTRICT;
ALTER TABLE "Respuesta" ADD CONSTRAINT "fk_respuesta_idopcionseleccionada_idpregunta" FOREIGN KEY ("idOpcionSeleccionada", "idPregunta") REFERENCES "OpcionRespuesta" ("idOpcion", "idPregunta") ON DELETE RESTRICT;
COMMIT;
